// Auto-generated logo assets with Vite module imports and guaranteed base64 fallbacks for GitHub Pages & static hosting
import logoLightUrl from "./ismaili-official-logo.png";
import logoDarkUrl from "./ismaili-official-logo-dark.png";
import emblemLightUrl from "./ismaili-emblem.png";
import emblemDarkUrl from "./ismaili-emblem-dark.png";

export const LOGO_ASSETS = {
  logoLight: logoLightUrl,
  logoDark: logoDarkUrl,
  emblemLight: emblemLightUrl,
  emblemDark: emblemDarkUrl,
  // Base64 fallbacks to ensure 100% reliability even if assets are served from custom GitHub subpaths
  fallbackLogoLight: "data:image/png;base64,",
  fallbackLogoDark: "data:image/png;base64,",
  fallbackEmblemLight: "data:image/png;base64,",
  fallbackEmblemDark: "data:image/png;base64,",
};

/**
 * Safely resolves an asset URL for any hosting environment (GitHub Pages subpaths, root domains, etc.)
 */
export function resolveAssetUrl(relativePath: string): string {
  const base = import.meta.env.BASE_URL || "./";
  const cleanBase = base.endsWith("/") ? base : base + "/";
  const cleanPath = relativePath.startsWith("/") ? relativePath.slice(1) : relativePath;
  return cleanBase + cleanPath;
}
